import gzip
import io
import json
import zipfile

import pytest

from tests.smoke_utils import run_cli
from wgsextract_cli.core import microarray_revisions as revisions
from wgsextract_cli.core.microarray_utils import _PACKAGED_TEMPLATES
from wgsextract_cli.core.utils import WGSExtractError

BASE = [(f"rs{i}", str(1 + i % 22), str(1000 + i)) for i in range(3000)]
# A silent same-version revision: 40 markers dropped and 25 added.
REVISED = BASE[40:] + [(f"i{i}", "X", str(5000 + i)) for i in range(25)]


def _export(
    rows,
    header=(
        "# This data file generated by 23andMe at: Thu Jul 14 06:39:17 2011",
        "# reference human assembly build 37 (also known as Annotation Release 104)",
    ),
):
    lines = [*header, "# rsid\tchromosome\tposition\tgenotype"]
    lines += [f"{marker}\t{chrom}\t{pos}\tAG" for marker, chrom, pos in rows]
    return "\n".join(lines) + "\n"


def _entry(name, rows, *, template=None, vendor="23andMe", declares=True):
    fp = revisions.fingerprint(rows)
    entry = {
        "id": name,
        "vendor": vendor,
        "chip": "v9",
        "revision": name,
        "build": "GRCh37",
        "markers": fp.markers,
        "ids_sha256": fp.ids_sha256,
        "sites_sha256": fp.sites_sha256,
        "sketch": revisions.encode_sketch(fp.sketch),
        "kind": "export",
        "declares_vendor": declares,
        "source": "test",
    }
    if template:
        entry["template"] = {
            "name": template,
            "formats": template.lower(),
            "relation": "exact",
            "added": 0,
            "removed": 0,
        }
    return entry


def _catalogue(tmp_path, *entries):
    path = tmp_path / "catalogue.json"
    path.write_text(
        json.dumps(
            {
                "format": "wgsextract-chip-revisions",
                "version": 1,
                "revisions": list(entries),
            }
        )
    )
    revisions.load_catalogue.cache_clear()
    return revisions.load_catalogue(path)


def test_header_layouts_and_containers(tmp_path):
    text = _export(BASE)
    plain = tmp_path / "genome.txt"
    plain.write_text(text)
    with gzip.open(tmp_path / "genome.txt.gz", "wt") as out:
        out.write(text)
    with zipfile.ZipFile(tmp_path / "genome.zip", "w") as archive:
        archive.writestr("genome.txt", text)
        archive.writestr("__MACOSX/._genome.txt", "")
    (tmp_path / "utf16.txt").write_bytes(text.encode("utf-16"))
    results = [
        revisions.read_raw_export(tmp_path / name)
        for name in ("genome.txt", "genome.txt.gz", "genome.zip", "utf16.txt")
    ]
    assert len({r.fingerprint.sites_sha256 for r in results}) == 1
    export = results[0]
    assert (
        export.vendor,
        export.declared_build,
        export.export_month,
        export.layout,
    ) == ("23andMe", "GRCh37", "2011-07", "tsv4")
    assert export.fingerprint.markers == 3000

    # MyHeritage quotes values but not its column header; Ancestry splits alleles.
    myheritage = tmp_path / "mh.csv"
    myheritage.write_text(
        "##fileformat=MyHeritage\n##chip=GSA\nRSID,CHROMOSOME,POSITION,RESULT\n"
        + "".join(f'"{m}","{c}","{p}","AG"\n' for m, c, p in BASE)
    )
    mh = revisions.read_raw_export(myheritage)
    assert (mh.vendor, mh.declared_chip, mh.layout) == ("MyHeritage", "GSA", "csv4")
    assert mh.fingerprint.ids_sha256 == export.fingerprint.ids_sha256
    ancestry = tmp_path / "AncestryDNA.txt"
    ancestry.write_text(
        "#AncestryDNA raw data download\n#This file was generated by "
        "AncestryDNA at: 03/29/2016 15:28:15 UTC\n#Data was collected using "
        "AncestryDNA array version: V2.0\nrsid\tchromosome\tposition\tallele1\tallele2\n"
        + "".join(f"{m}\t{c}\t{p}\tA\tG\n" for m, c, p in BASE)
    )
    anc = revisions.read_raw_export(ancestry)
    assert (anc.vendor, anc.declared_chip, anc.export_month, anc.layout) == (
        "AncestryDNA",
        "V2.0",
        "2016-03",
        "tsv5",
    )

    bad = tmp_path / "bad.txt"
    bad.write_text("rs1\t1\n")
    with pytest.raises(WGSExtractError, match="marker row 1"):
        revisions.read_raw_export(bad)


def test_identical_markers_match_exactly_and_coordinates_separate_builds(tmp_path):
    shifted = [(m, c, str(int(p) + 7)) for m, c, p in BASE]
    catalogue = _catalogue(tmp_path, _entry("base", BASE), _entry("revised", REVISED))
    file = tmp_path / "f.txt"
    file.write_text(_export(list(reversed(BASE))))
    detection = revisions.detect(revisions.read_raw_export(file), catalogue)
    assert (detection.best.revision.id, detection.best.match, detection.confidence) == (
        "base",
        "exact",
        1.0,
    )
    file.write_text(_export(shifted))
    detection = revisions.detect(revisions.read_raw_export(file), catalogue)
    assert (detection.best.revision.id, detection.best.match) == ("base", "markers")


def test_unseen_layout_scores_exactly_against_installed_templates(tmp_path):
    root = tmp_path / "raw_file_templates"
    (root / "body").mkdir(parents=True)
    for name, rows in (("Nucleus_V1", BASE), ("LDNA_V1", REVISED)):
        (root / "body" / f"{name}.txt").write_text(
            "".join(f"{m}\t{c}\t{p}\n" for m, c, p in rows)
        )
    catalogue = _catalogue(
        tmp_path,
        _entry("base", BASE, template="Nucleus_V1"),
        _entry("revised", REVISED, template="LDNA_V1"),
        _entry("other_vendor", BASE, vendor="AncestryDNA"),
    )
    # One marker more than the revised layout, e.g. a newer silent revision.
    rows = [*REVISED, ("rs99999", "1", "99")]
    export = revisions.parse_raw_export(io.StringIO(_export(rows)), "f")
    estimated = revisions.detect(export, catalogue)
    assert not estimated.best.exact_score
    exact = revisions.detect(export, catalogue, [str(root)])
    assert exact.best.revision.id == "revised" and exact.best.exact_score
    assert exact.best.score == pytest.approx(len(REVISED) / (len(REVISED) + 1))
    assert exact.candidates[1].score < exact.best.score
    assert not exact.ambiguous and exact.confidence == round(exact.best.score, 4)
    # The header names 23andMe, so the AncestryDNA revision is never a candidate.
    assert "other_vendor" not in {c.revision.id for c in exact.candidates}


def test_files_without_a_vendor_header_skip_self_declaring_vendors(tmp_path):
    catalogue = _catalogue(
        tmp_path,
        _entry("mh", BASE, vendor="MyHeritage"),
        _entry("ftdna", BASE[1:], vendor="FamilyTreeDNA", declares=False),
    )
    file = tmp_path / "f.csv"
    file.write_text(
        "RSID,CHROMOSOME,POSITION,RESULT\n"
        + "".join(f'"{m}","{c}","{p}","AG"\n' for m, c, p in BASE)
    )
    detection = revisions.detect(revisions.read_raw_export(file), catalogue)
    assert [c.revision.id for c in detection.candidates] == ["ftdna"]


def test_packaged_catalogue_matches_packaged_templates():
    revisions.load_catalogue.cache_clear()
    catalogue = revisions.load_catalogue()
    linked = {r.template: r for r in catalogue if r.template_relation == "exact"}
    for body in sorted((_PACKAGED_TEMPLATES / "body").glob("*.gz")):
        name = body.name.split(".")[0]
        ids = revisions.template_ids(name, [str(_PACKAGED_TEMPLATES)])
        assert name in linked, name
        assert ids is not None and len(ids) == linked[name].markers


def test_info_chip_cli(tmp_path):
    body = _PACKAGED_TEMPLATES / "body" / "Ancestry_V2_2024.txt.gz"
    with gzip.open(body, "rt") as source:
        rows = [line.split("\t")[:3] for line in source]
    export = tmp_path / "AncestryDNA.txt"
    export.write_text(
        "#AncestryDNA raw data download\n#Data was collected using AncestryDNA "
        "array version: V2.0\nrsid\tchromosome\tposition\tallele1\tallele2\n"
        + "".join(f"{m}\t{c}\t{p.strip()}\t0\t0\n" for m, c, p in rows)
    )
    rc, stdout, stderr = run_cli(["info", "chip", "--input", str(export), "--json"])
    assert rc == 0, stderr
    result = json.loads(stdout)
    best = result["candidates"][0]
    assert result["confidence"] == 1.0 and best["match"] == "exact"
    assert best["revision"]["template"]["formats"] == "ancestry_v2_2024"
    rc, stdout, stderr = run_cli(["info", "chip", "--list"])
    assert rc == 0 and "ancestry_v2_2024" in stdout, stderr


def test_catalogue_builder_labels_corpus_groups_against_templates(tmp_path):
    from scripts.microarray_chip_catalogue import build

    root = tmp_path / "raw_file_templates"
    (root / "body").mkdir(parents=True)
    (root / "body" / "Nucleus_V1.txt").write_text(
        "".join(f"{m}\t{c}\t{p}\n" for m, c, p in BASE)
    )
    workdir = tmp_path / "corpus"
    (workdir / "sites").mkdir(parents=True)
    fp = revisions.fingerprint(REVISED)
    with gzip.open(workdir / "sites" / f"{fp.sites_sha256}.tsv.gz", "wt") as out:
        out.write("".join(f"{m}\t{c}\t{p}\n" for m, c, p in REVISED))
    record = {
        "vendor": "FamilyTreeDNA",
        "build": "GRCh37",
        "markers": fp.markers,
        "ids_sha256": fp.ids_sha256,
        "sites_sha256": fp.sites_sha256,
        "sketch": revisions.encode_sketch(fp.sketch),
    }
    (workdir / "fingerprints.jsonl").write_text(
        "".join(
            json.dumps({**record, "member": i, "month": f"2016-0{i + 1}"}) + "\n"
            for i in range(3)
        )
        + json.dumps({"member": 3, "error": "no marker rows"})
        + "\n"
    )
    label = {"chip": "v1", "build": "GRCh37", "declares_vendor": False}
    spec = tmp_path / "spec.json"
    spec.write_text(
        json.dumps(
            {
                "templates": ["Nucleus_V1"],
                "revisions": [
                    {
                        **label,
                        "id": "nucleus_v1",
                        "template": "Nucleus_V1",
                        "vendor": "Nucleus",
                        "revision": "t",
                        "kind": "export",
                    },
                    {
                        **label,
                        "id": "ftdna_2016",
                        "group": fp.ids_sha256,
                        "vendor": "FamilyTreeDNA",
                        "revision": "c",
                        "kind": "export",
                    },
                ],
            }
        )
    )
    output = tmp_path / "catalogue.json"
    build(workdir, [str(root)], spec, output)
    revisions.load_catalogue.cache_clear()
    template, group = revisions.load_catalogue(output)
    assert (template.template_relation, template.exports) == ("exact", 0)
    assert (group.exports, group.period, group.markers) == (3, "2016-01/2016-03", 2985)
    assert (group.template, group.template_relation) == ("Nucleus_V1", "closest")
    assert (group.template_added, group.template_removed) == (25, 40)
